//! The generated packers against Mesa's own, on the same values.
//!
//! Mesa's generator (third_party/mesa-26.2.1/src/panfrost/genxml/gen_pack.py,
//! unmodified) makes v10_pack.h from the vendored v10.xml; our generator
//! writes the cases as C (`tools/mali/gen_pack_rs.py c-cases`) and
//! tools/mali/pack_ref.c packs them with Mesa's macros, built without
//! NDEBUG so Mesa's own asserts stand behind every value. The same cases
//! as Rust are `v10_cases`, committed and regenerated by tools/check.sh. The
//! test needs python3 and a C compiler on the host and fails without them:
//! a cross-check that did not run is not a pass.
//!
//! Population: every struct Mesa packs directly ([`PACKABLE_STRUCTS`] of
//! them), each with a defaults case and cases that give every field a
//! non-zero encoding; the GLES2 structs of driver/docs/nanopc-t6-mali.md
//! are named and must be there.

use super::v10::UNSET_ENUM_LEAVES;
use super::v10_cases::cases;
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};
use std::process::Command;

const XML: &str = "third_party/mesa-26.2.1/src/panfrost/genxml/v10.xml";

/// The structs of v10.xml Mesa emits a `_pack` for (no `no-direct-packing`,
/// a whole number of words). Pinned: a v10.xml with more or fewer fails
/// here, and the number is derived again rather than widened.
const PACKABLE_STRUCTS: usize = 100;

/// The defaults cases whose Mesa header sets two members of one union: Mesa
/// packs them ORed, the packer refuses (`CaseOut::refused`). Today one,
/// Render Target (its YUV and AFBC YUV arms both default `YUV Enable` to
/// true); the arms themselves pack their defaults like Mesa.
const REFUSED_UNION_DEFAULTS: usize = 1;

/// The other planned refusal: Mesa's header leaves an enum without a default
/// at zero, which the enum does not name (`UNSET_ENUM_LEAVES`). Such a
/// struct's defaults case is refused with this message; its `defaults_named`
/// case (a named value in each of those fields) is compared with Mesa.
const UNSET_MESSAGE: &str = ": enum value 0 is not a named value";

/// The descriptors the GLES2 frame needs (the design page, "The command
/// stream and descriptors"), by their Rust names.
const GLES2_STRUCTS: [&str; 18] = [
    "FramebufferParameters",
    "RenderTarget",
    "TilerContext",
    "TilerHeap",
    "ShaderProgram",
    "Resource",
    "Attribute",
    "Buffer",
    "Texture",
    "Sampler",
    "Blend",
    "DepthStencil",
    "LocalStorage",
    "Scissor",
    "PrimitiveFlags",
    "DcdFlags0",
    "DcdFlags1",
    "DcdFlags2",
];

fn run(cmd: &mut Command, what: &str) -> Vec<u8> {
    let out = cmd.output().unwrap_or_else(|e| panic!("{what}: cannot run: {e}"));
    assert!(
        out.status.success(),
        "{what}: {}\n{}",
        out.status,
        String::from_utf8_lossy(&out.stderr).lines().take(40).collect::<Vec<_>>().join("\n")
    );
    out.stdout
}

/// Mesa's bytes for every case, by case id, in the order printed.
fn mesa_bytes(root: &Path, dir: &Path) -> Vec<(String, Vec<u8>)> {
    let py = |args: &[&str], what: &str| {
        run(Command::new("python3").current_dir(root).env("PYTHONDONTWRITEBYTECODE", "1").args(args), what)
    };
    let header = py(&["third_party/mesa-26.2.1/src/panfrost/genxml/gen_pack.py", XML], "Mesa's gen_pack.py");
    /* Mesa's own population, counted apart from our generator's case ids */
    let macros = String::from_utf8_lossy(&header)
        .lines()
        .filter(|l| {
            l.strip_prefix("#define MALI_")
                .is_some_and(|r| r.split('(').next().is_some_and(|n| n.ends_with("_pack")) && r.contains('('))
        })
        .count();
    assert_eq!(macros, PACKABLE_STRUCTS, "the MALI_*_pack macros of Mesa's v10_pack.h");
    std::fs::write(dir.join("v10_pack.h"), header).expect("write v10_pack.h");
    let inc = py(&["tools/mali/gen_pack_rs.py", "c-cases", XML], "gen_pack_rs.py c-cases");
    std::fs::write(dir.join("v10_cases.inc"), inc).expect("write v10_cases.inc");
    let bin = dir.join("pack_ref");
    run(
        Command::new("cc")
            .current_dir(root)
            .args(["-std=gnu11", "-O1", "-Wall", "-Werror"])
            .args(["-DUTIL_ARCH_LITTLE_ENDIAN=1", "-DUTIL_ARCH_BIG_ENDIAN=0"])
            .arg("-I")
            .arg(dir)
            .args(["-Ithird_party/mesa-26.2.1/src/panfrost", "-Ithird_party/mesa-26.2.1/src"])
            .args(["-Ithird_party/mesa-26.2.1/include", "tools/mali/pack_ref.c", "-lm", "-o"])
            .arg(&bin),
        "cc tools/mali/pack_ref.c",
    );
    let out = String::from_utf8(run(&mut Command::new(&bin), "pack_ref")).expect("ASCII");
    let mut cases = Vec::new();
    let mut summary = None;
    for line in out.lines() {
        if let Some(rest) = line.strip_prefix("case ") {
            let (id, hex) = rest.split_once(' ').expect("case <id> <hex>");
            let bytes =
                (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex")).collect();
            cases.push((id.to_string(), bytes));
        } else if line.starts_with("cases ") {
            summary = Some(line.to_string());
        }
    }
    let summary = summary.expect("pack_ref printed no summary: it did not finish");
    assert_eq!(summary, format!("cases {} (planned {})", cases.len(), cases.len()), "pack_ref's own count");
    cases
}

#[test]
fn every_struct_packs_to_the_bytes_of_mesa_s_own_packer() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    /* the test's own scratch (written, not read as input), as
     * yakogl-precompile's tests name theirs */
    let dir = PathBuf::from(format!("{}/build/test-tmp/mali-genxml-{}", root.display(), std::process::id()));
    std::fs::create_dir_all(&dir).expect("the scratch directory");
    let mesa = mesa_bytes(&root, &dir);
    let _ = std::fs::remove_dir_all(&dir);

    let ours = cases();
    let ids: Vec<&str> = ours.iter().map(|(id, _)| *id).collect();
    let mesa_ids: Vec<&str> = mesa.iter().map(|(id, _)| id.as_str()).collect();
    assert_eq!(ids, mesa_ids, "the two sides ran different cases (the committed v10_cases.rs is stale?)");

    let mut per_struct: BTreeMap<&str, usize> = BTreeMap::new();
    let (mut differ, mut round_trips) = (Vec::new(), 0usize);
    let mut round_tripped = BTreeSet::new();
    /* the structs (v10.xml names) whose defaults case was refused, by cause */
    let (mut refused_shared, mut refused_unset) = (BTreeSet::new(), BTreeSet::new());
    for ((id, case), (_, want)) in ours.iter().zip(&mesa) {
        *per_struct.entry(id.split('/').next().expect("struct/case")).or_default() += 1;
        let out = case();
        if let Some(why) = out.refused {
            /* Mesa's header sets two members of a union and Mesa ORs them;
             * the packer must refuse, with exactly this message */
            match &out.bytes {
                Err(e) if e.to_string() == why => {
                    let structure =
                        why.strip_prefix("mali ").and_then(|w| w.split('.').next()).expect("mali <struct>.");
                    if why.ends_with(UNSET_MESSAGE) { &mut refused_unset } else { &mut refused_shared }
                        .insert(structure.to_string());
                }
                Err(e) => differ.push(format!("{id}: refused, but as {e}, not as {why}")),
                Ok(_) => differ.push(format!("{id}: packed a union Mesa's header sets two members of")),
            }
            continue;
        }
        match &out.bytes {
            Ok(b) if b == want => {}
            Ok(b) => differ.push(format!("{id}: ours {b:02x?}\n    Mesa {want:02x?}")),
            Err(e) => differ.push(format!("{id}: refused a value Mesa packs: {e}")),
        }
        match out.round_trip {
            None => {}
            Some(Ok(true)) => {
                round_trips += 1;
                round_tripped.insert(id.split('/').next().expect("struct/case"));
            }
            Some(Ok(false)) => differ.push(format!("{id}: unpack gave another value back")),
            Some(Err(e)) => differ.push(format!("{id}: unpack refused our own bytes: {e}")),
        }
    }
    eprintln!(
        "mali genxml vs Mesa: {} cases run (planned {}), {} differing, {} refused as planned; {} structs, {} round trips",
        ours.len(),
        mesa.len(),
        differ.len(),
        refused_shared.len() + refused_unset.len(),
        per_struct.len(),
        round_trips
    );
    assert!(differ.is_empty(), "{} of {} cases differ:\n{}", differ.len(), ours.len(), differ.join("\n"));
    assert_eq!(per_struct.len(), PACKABLE_STRUCTS, "the packable structs of v10.xml");
    for s in GLES2_STRUCTS {
        /* a defaults case and at least three with every field encoded non-zero */
        let n = per_struct.get(s).copied().unwrap_or(0);
        assert!(n >= 4, "{s}: {n} cases");
    }
    assert!(round_trips > 0, "no struct was unpacked");
    /* unpack() or, where fields share bits, unpack_as(arm): every packable
     * struct is read back */
    assert_eq!(round_tripped.len(), PACKABLE_STRUCTS, "the structs with a round trip");
    /* Render Target's header: the YUV arms' YUV Enable defaults (pinned so
     * that a changed population is looked at, not absorbed) */
    assert_eq!(
        refused_shared.len(),
        REFUSED_UNION_DEFAULTS,
        "the defaults cases that must be refused: {refused_shared:?}"
    );
    /* every struct with a default-less enum that has no zero is refused at its
     * defaults, by the union rule first where that one applies; the structs come
     * from the packer's own list of those fields, whose count tests.rs derives
     * from the XML */
    let unset_structs: BTreeSet<String> =
        UNSET_ENUM_LEAVES.iter().map(|l| l.split('.').next().expect("struct.field").to_string()).collect();
    let expected: BTreeSet<String> = unset_structs.difference(&refused_shared).cloned().collect();
    assert_eq!(refused_unset, expected, "the defaults cases refused for an unset enum");
}
